<div class="form-grid"><label>First name<input name="first_name" value="{{ old('first_name',$member->first_name ?? '') }}" required></label><label>Last name<input name="last_name" value="{{ old('last_name',$member->last_name ?? '') }}" required></label><label>Email<input type="email" name="email" value="{{ old('email',$member->email ?? '') }}" required></label><label>Phone<input name="phone" value="{{ old('phone',$member->phone ?? '') }}" required></label><label>Category<select name="membership_category_id" required>@foreach($categories as $category)<option value="{{ $category->id }}" @selected(old('membership_category_id',$member->membership_category_id ?? '')==$category->id)>{{ $category->name }}</option>@endforeach</select></label><label>Level<select name="membership_level_id" required>@foreach($levels as $level)<option value="{{ $level->id }}" @selected(old('membership_level_id',$member->membership_level_id ?? '')==$level->id)>{{ $level->name }} - ₱{{ number_format($level->fee,2) }}</option>@endforeach</select></label><label>Birthdate<input type="date" name="birthdate" value="{{ old('birthdate',isset($member) ? optional($member->birthdate)->format('Y-m-d') : '') }}"></label><label class="full">Address<textarea name="address">{{ old('address',$member->address ?? '') }}</textarea></label></div>
